    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.25/codesynapse-linux-arm64"
      sha256 "b1ce55933579a62d1a8291f09fd81b337d73ac98dcffa1fbd11e40379abe3058"
